function validateEncounter(e){if(e.displacementSkills===undefined)return;need(e.displacementSkills&&typeof e.displacementSkills==='object'&&!Array.isArray(e.displacementSkills)&&Object.keys(e.displacementSkills).length<=30,'ข้อมูลผลัก/ดึงในสนามไม่ถูกต้อง');const N=g.DecideCreation||(typeof require==='function'?require('./creation-data.js'):null);for(const [id,v]of Object.entries(e.displacementSkills)){need(N.skills[id]?.power>0,'ท่านี้ยังไม่รองรับผลัก/ดึง');validate(v);}}
