for(let step=0;step<limit;step++){const at=result.to,x=at%s.w,y=Math.floor(at/s.w),dx=x-ox,dy=y-oy;if(!dx&&!dy){result.reason='ไม่มีทิศทาง';break;}const sign=v.push?1:-1,mx=Math.abs(dx)>=Math.abs(dy)?Math.sign(dx)*sign:0,my=mx?0:Math.sign(dy)*sign,nx=x+mx,ny=y+my;if(nx<0||nx>=s.w||ny<0||ny>=s.h){result.reason='ขอบสนาม';break;}const next=ny*s.w+nx,parts=footprint(s,target,next),before=footprint(s,target,at);if(!parts.length||!before.length){result.reason='ขอบสนาม';break;}if(known&&parts.some(i=>!known.has(i))){result.reason='นอกพื้นที่มองเห็น';break;}if(parts.some(i=>!D.walkable(s.cells[i])||s.cells[i].object==='tree')){result.reason='สิ่งกีดขวาง';break;}if(parts.some((i,k)=>s.cells[i].height!==s.cells[before[k]].height)){result.reason='ช่องต่างระดับ';break;}if(parts.some(i=>occupied.has(i))){result.reason='ตัวละครขวาง';break;}result.path.push(next);result.to=next;const trap=(e.traps||[]).find(t=>parts.includes(t.index));if(trap){result.reason='กับดักหยุดเคลื่อนที่';result.trap=trap.index;break;}}
