function apply(e,source,target,v){const out=trace(e,source,target,v);if(!active(v)||source.id===target.id||target.hp<=0)return out;const H=g.DecideGridHazards||(typeof require==='function'?require('./grid-hazards.js'):null),planned=out.path;out.path=[];for(const cell of planned){target.n=D.node(cell);out.path.push(cell);out.to=cell;H.enter(e,target);if(!target.hp){out.reason='ล้มลงในพื้นที่';out.trap=null;break;}}if(out.trap!==null)e.traps=e.traps.filter(t=>t.index!==out.trap);const text=target.name+' • '+describe(v)+' → '+out.path.length+' ช่อง'+(out.reason?' • หยุด: '+out.reason:'');e.log.unshift(text);e.log=e.log.slice(0,30);return out;}
