function previewText(scene,rows){const xy=i=>(i%scene.w+1)+','+(Math.floor(i/scene.w)+1);return rows.map(r=>r.name+' ('+xy(r.from)+') → ('+xy(r.to)+')'+(r.reason?' · '+r.reason:'')).join(' • ');}
function commandPreview(e,id,ids,aim,options={}){const C=g.DecideCombatRules||(typeof require==='function'?require('./tactical-systems.js'):null),N=g.DecideCreation||(typeof require==='function'?require('./creation-data.js'):null),G=g.DecideGridPatterns||(typeof require==='function'?require('./grid-patterns.js'):null),p=C.hero(e),a=(e.catalogActions||[]).find(a=>a.id===id)||N.skills[id],v=a?.displacement||config(e,id);if(!a||a.hazard||e.hazardSkills?.[id]||!active(v))return [];try{const shape=a.grid||e.gridSkills?.[id],rule=id.startsWith('catalog-')?a.targeting:C.tactical.profile(e,'skill:'+id,a.targeting);let targets=shape?G.targets(e,p,shape,ids,aim,e.gridDirection??-1,a.targeting.side,a.magic):C.tactical.targets(e,p,ids,rule);if(!shape&&id==='fire'){const t=targets[0];targets=e.units.filter(u=>u.hp>0&&C.distance(e.scene,u.n,t.n)<=1&&C.tactical.canTarget(e,p,u,rule));}if(!shape&&id==='cleave'){const pi=D.index(p.n),ti=D.index(targets[0].n),dx=ti%e.scene.w-pi%e.scene.w,dy=Math.floor(ti/e.scene.w)-Math.floor(pi/e.scene.w);targets=e.units.filter(u=>{const i=D.index(u.n),x=i%e.scene.w-pi%e.scene.w,y=Math.floor(i/e.scene.w)-Math.floor(pi/e.scene.w);return u!==p&&u.hp>0&&(dx?x===Math.sign(dx)&&Math.abs(y)<=1:y===Math.sign(dy)&&Math.abs(x)<=1)&&C.tactical.canTarget(e,p,u,rule);});}return preview(e,p,targets,v,options).filter(r=>r.id!==p.id);}catch{return [];}}
